function sent(g){const marker=`CHANNEL_OUTPUT_${g}`;return http.some(x=>JSON.stringify(x.body).includes(marker)&&!x.path.startsWith('/v1/'))||wire.some(x=>x.cmd==='aibot_respond_msg'&&JSON.stringify(x.body).includes(marker))}
