async function deliver(text,g){const initial=text===`CHANNEL_INPUT_${g}`,row={generation:g,text,time:Date.now()};if(['telegram','weixin'].includes(kind)){if(initial)inbound.push(row);pending.push(text);}else{await wait(()=>[...peers].some(p=>p.readyForInput),'peer ready');for(const p of peers)if(p.readyForInput){const frame=inputFrame(text);if(initial){row.frame=Buffer.isBuffer(frame)?{rawBytesHex:frame.toString('hex')}:frame;if(kind==='qq'||kind==='discord')row.messageId=frame.d.id;if(kind==='wecom')row.reqId=frame.headers.req_id;inbound.push(row);}send(p,frame);}}}
async function incoming(g){const hs=http.length,ws=wire.length;await deliver(`CHANNEL_INPUT_${g}`,g);await wait(()=>sentText('回复 1 允许一次',hs,ws),'actual permission prompt '+g);const file=join(project,`permission-${g}.txt`);const exists=await readFile(file).then(()=>true,()=>false);permissionGate.push({generation:g,fileExistsBeforeAnswer:exists,path:file});assert.equal(exists,false);await deliver('1',g);answerSent.push({generation:g,kind:'permission',text:'1',time:Date.now()});await wait(()=>sentText('Choose mock option',hs,ws),'actual elicitation prompt '+g);assert.equal(await readFile(file,'utf8'),'approved');await deliver('1',g);answerSent.push({generation:g,kind:'elicitation',text:'1',time:Date.now()});await wait(()=>models.some(x=>x.stream&&JSON.stringify(x.messages).includes(`CHANNEL_INPUT_${g}`)),'actual A7 model '+g);steps.push({event:'actual-model',generation:g,time:Date.now()});await wait(()=>sent(g),'actual outbound '+g);steps.push({event:'actual-outbound',generation:g,time:Date.now()});}

