await reload(false,'disable');await wait(()=>peers.size===0,'disabled sockets');steps.push({event:'disabled-sockets-closed',time:Date.now()});await delay(150);generation=1;await reload(true,'enable');await incoming(1);control.close();child.kill('SIGTERM');exit=await Promise.race([stopped,delay(12000).then(()=>({code:null,signal:'timeout'}))]);assert.equal(exit.code,0);await wait(()=>peers.size===0,'shutdown sockets');steps.push({event:'actual-process-stop',exit,time:Date.now()});steps.push({event:'complete',status:'PASS'});
